begin;
create type public.nc_status as enum ('open','investigating','action_planned','implemented','effectiveness_review','closed','cancelled');
create table public.nonconformities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),chapter_id smallint references public.chapters(id),criterion_id uuid references public.criteria(id),code text not null,title text not null,description text not null,severity text not null check(severity in ('low','medium','high','critical')),status public.nc_status not null default 'open',reported_by uuid not null references public.profiles(id),reported_at timestamptz not null default now(),due_date date,closed_at timestamptz,unique(laboratory_id,code));
create table public.capa_actions(id uuid primary key default gen_random_uuid(),nonconformity_id uuid not null references public.nonconformities(id) on delete cascade,action_type text not null check(action_type in ('correction','corrective','preventive')),description text not null,responsible_id uuid not null references public.profiles(id),due_date date not null,status text not null default 'open' check(status in ('open','in_progress','completed','cancelled')),completed_at timestamptz,created_at timestamptz not null default now());
create table public.capa_effectiveness_reviews(id uuid primary key default gen_random_uuid(),action_id uuid not null references public.capa_actions(id) on delete restrict,reviewed_by uuid not null references public.profiles(id),reviewed_at timestamptz not null default now(),effective boolean not null,evidence text not null,follow_up_required boolean not null default false);
create index nonconformities_scope_idx on public.nonconformities(organization_id,laboratory_id,status,due_date);
create index capa_due_idx on public.capa_actions(status,due_date);
alter table public.nonconformities enable row level security; alter table public.capa_actions enable row level security; alter table public.capa_effectiveness_reviews enable row level security;
create policy nc_read_scope on public.nonconformities for select to authenticated using(public.is_lab_admin() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved' and p.laboratory_id=nonconformities.laboratory_id));
create policy nc_create_scope on public.nonconformities for insert to authenticated with check(public.has_permission('create') and exists(select 1 from public.profiles p where p.id=auth.uid() and p.laboratory_id=nonconformities.laboratory_id));
commit;
